import type { CalendarImpactItem, ProjectRuntimeSettings, RuntimeSettingCategory, UserSession } from '@pacom/contracts';
import { E7F_IDS, type PacomDataAdapter } from '../../adapters';

type SettingNavId = RuntimeSettingCategory | 'notifications';

const SETTING_GROUPS: Array<{
  group: string;
  items: Array<{ id: SettingNavId; label: string }>;
}> = [
  {
    group: '项目基准',
    items: [
      { id: 'calendar', label: '运行日历' },
      { id: 'weather_area', label: '气象与面积' },
      { id: 'metering_carbon', label: '计量与碳排' },
    ],
  },
  {
    group: '通知与模板',
    items: [
      { id: 'notifications', label: '告警通知订阅' },
      { id: 'templates', label: '参数模板' },
    ],
  },
];

const ALL_CATEGORIES = SETTING_GROUPS.flatMap((g) => g.items);

export async function mountSettingsView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  session: UserSession
): Promise<void> {
  let category: SettingNavId = 'calendar';
  let data: ProjectRuntimeSettings = await adapter.getRuntimeSettings(E7F_IDS.projectId);
  let draftStart = data.calendar.workdayStart;
  let draftEnd = data.calendar.workdayEnd;
  let impacts: CalendarImpactItem[] = [];
  const notifyPrefs = { criticalSms: true, inAppBanner: true, dailyDigest: false };
  let notice = '';
  let errorMsg = '';

  function render(): void {
    const filteredRules = data.rules.filter((r) => r.category === category);
    const activeCatLabel = ALL_CATEGORIES.find((c) => c.id === category)?.label ?? '运行设置';
    const canEdit = session.scope.canEditDeployment;

    root.innerHTML = `
      <div class="pacom-shell">
        <header class="pacom-header">
          <div class="pacom-header-top">
            <h1 class="pacom-title">运行设置</h1>
            <div class="pacom-header-meta">
              <span class="pacom-badge pacom-badge--neutral">项目范围：广实2号园</span>
              <span class="pacom-badge ${canEdit ? 'pacom-badge--online' : 'pacom-badge--warning'}">
                ${canEdit ? '可修改并下发配置' : '当前角色只读'}
              </span>
            </div>
          </div>
        </header>

        ${notice ? `<div class="lov-banner lov-banner--ok"><span class="lov-banner-title">${notice}</span></div>` : ''}
        ${errorMsg ? `<div class="pacom-alert-banner">${errorMsg}</div>` : ''}

        <div class="lov-subnav-layout">
          <nav class="lov-subnav-rail" aria-label="运行设置分组">
            ${SETTING_GROUPS.map(
              (grp) => `
              <div class="lov-subnav-group">
                <div class="lov-subnav-group-title">${grp.group}</div>
                ${grp.items
                  .map((item) => {
                    const ruleCount = item.id === 'calendar' ? '' : String(data.rules.filter((r) => r.category === item.id).length);
                    return `
                      <button class="lov-subnav-item" aria-current="${category === item.id ? 'true' : 'false'}" data-scat="${item.id}">
                        <span>${item.label}</span>
                        ${ruleCount ? `<span class="pacom-badge pacom-badge--neutral">${ruleCount}</span>` : ''}
                      </button>`;
                  })
                  .join('')}
              </div>`
            ).join('')}
          </nav>

          <div class="lov-subnav-main">
            ${
              category === 'calendar'
                ? `
                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">项目工作时间日历</h2>
                    <span class="pacom-badge pacom-badge--neutral">版本 v${data.calendar.version}</span>
                  </div>
                  <div class="lov-settings-card">
                    <div class="lov-setting-row">
                      <div class="lov-setting-meta">
                        <span class="lov-setting-title">工作日上班时间</span>
                        <span class="lov-setting-desc">用于自动触发早间预冷/预热及公共区域照明启动</span>
                      </div>
                      <div class="lov-setting-control">
                        <input class="pacom-input" style="width:140px;" type="time" data-cal-start value="${draftStart}" ${!canEdit ? 'disabled' : ''} />
                      </div>
                    </div>
                    <div class="lov-setting-row">
                      <div class="lov-setting-meta">
                        <span class="lov-setting-title">工作日下班时间</span>
                        <span class="lov-setting-desc">夜间巡检窗口为 ${data.calendar.nightGuardStart} – ${data.calendar.nightGuardEnd}；若晚于 21:30 将自动提示交叠冲突</span>
                      </div>
                      <div class="lov-setting-control">
                        <input class="pacom-input" style="width:140px;" type="time" data-cal-end value="${draftEnd}" ${!canEdit ? 'disabled' : ''} />
                      </div>
                    </div>
                    <div class="lov-setting-row" style="justify-content:flex-end;">
                      <button class="pacom-btn" data-preview-impact="1">预览受影响规则</button>
                      <button class="pacom-btn pacom-btn--primary" data-save-cal="1" ${!canEdit ? 'disabled' : ''}>保存并校验版本</button>
                    </div>
                  </div>
                </section>

                ${
                  impacts.length > 0
                    ? `
                    <section class="lov-section">
                      <div class="lov-section-head">
                        <h2 class="lov-section-title">受影响的定时与夜间规则预览</h2>
                        <span class="pacom-row-sub">共 ${impacts.length} 条</span>
                      </div>
                      <div class="lov-table-card">
                        <div class="lov-table-wrap">
                          <table class="lov-table">
                            <thead>
                              <tr>
                                <th>规则名称</th>
                                <th>原时间窗口</th>
                                <th>变更后窗口</th>
                                <th>影响评估</th>
                              </tr>
                            </thead>
                            <tbody>
                              ${impacts
                                .map(
                                  (im) => `
                                  <tr>
                                    <td>
                                      <div style="font-weight:500;">${im.ruleName}</div>
                                      ${im.conflictWarning ? `<div class="pacom-row-sub" style="color:var(--pacom-status-critical);">${im.conflictWarning}</div>` : ''}
                                    </td>
                                    <td>${im.beforeWindow}</td>
                                    <td><strong>${im.afterWindow}</strong></td>
                                    <td>
                                      <span class="pacom-badge ${im.conflictWarning ? 'pacom-badge--critical' : 'pacom-badge--accent'}">
                                        ${im.conflictWarning ? '交叠警告' : '自动跟随'}
                                      </span>
                                    </td>
                                  </tr>`
                                )
                                .join('')}
                            </tbody>
                          </table>
                        </div>
                      </div>
                    </section>`
                    : ''
                }`
                : category === 'notifications'
                  ? `
                  <section class="lov-section">
                    <div class="lov-section-head">
                      <h2 class="lov-section-title">告警与运行简报通知订阅</h2>
                      <span class="pacom-row-sub">按通道订阅本楼层关键动态</span>
                    </div>
                    <div class="lov-settings-card">
                      <div class="lov-setting-row">
                        <div class="lov-setting-meta">
                          <span class="lov-setting-title">严重告警短信与移动推送</span>
                          <span class="lov-setting-desc">触发严重级别告警或边缘网关断流超过 5 分钟时立即推送值班人</span>
                        </div>
                        <div class="lov-setting-control">
                          <button type="button" class="lov-switch" role="switch" aria-checked="${notifyPrefs.criticalSms}" data-notify-key="criticalSms" aria-label="严重告警短信推送">
                            <span class="lov-switch-thumb"></span>
                          </button>
                        </div>
                      </div>
                      <div class="lov-setting-row">
                        <div class="lov-setting-meta">
                          <span class="lov-setting-title">站内顶部实时横幅提醒</span>
                          <span class="lov-setting-desc">新告警与工单状态变更实时在工作区提示</span>
                        </div>
                        <div class="lov-setting-control">
                          <button type="button" class="lov-switch" role="switch" aria-checked="${notifyPrefs.inAppBanner}" data-notify-key="inAppBanner" aria-label="站内实时横幅提醒">
                            <span class="lov-switch-thumb"></span>
                          </button>
                        </div>
                      </div>
                      <div class="lov-setting-row">
                        <div class="lov-setting-meta">
                          <span class="lov-setting-title">每日运行与能耗晨间简报</span>
                          <span class="lov-setting-desc">每日 08:30 自动汇总昨日能耗偏差、未结工单与舒适度达标率</span>
                        </div>
                        <div class="lov-setting-control">
                          <button type="button" class="lov-switch" role="switch" aria-checked="${notifyPrefs.dailyDigest}" data-notify-key="dailyDigest" aria-label="每日运行简报">
                            <span class="lov-switch-thumb"></span>
                          </button>
                        </div>
                      </div>
                    </div>
                  </section>`
                  : `
                <section class="lov-section">
                  <div class="lov-section-head">
                    <h2 class="lov-section-title">${activeCatLabel}</h2>
                    <span class="pacom-row-sub">共 ${filteredRules.length} 条策略</span>
                  </div>
                  <div class="lov-settings-card">
                    ${
                      filteredRules.length === 0
                        ? `<div class="lov-empty-state"><strong>暂无配置项</strong><span>该分类下尚未定义运行策略规则。</span></div>`
                        : filteredRules
                            .map(
                              (r) => `
                              <div class="lov-setting-row">
                                <div class="lov-setting-meta">
                                  <span class="lov-setting-title">
                                    <span>${r.name}</span>
                                    <span class="pacom-badge pacom-badge--neutral">v${r.version}</span>
                                    <span class="pacom-badge pacom-badge--accent">${r.scopeLabel}</span>
                                  </span>
                                  <span class="lov-setting-desc">${r.summary} · 回执：${r.receiptSummary ?? '已同步'}</span>
                                </div>
                                <div class="lov-setting-control">
                                  <span class="pacom-row-sub">${r.enabled ? '已启用' : '已停用'}</span>
                                  <button
                                    type="button"
                                    class="lov-switch"
                                    role="switch"
                                    aria-checked="${r.enabled ? 'true' : 'false'}"
                                    aria-label="切换 ${r.name}"
                                    data-toggle-rule="${r.id}"
                                    data-rule-ver="${r.version}"
                                    data-rule-next="${!r.enabled}"
                                    ${!canEdit ? 'disabled' : ''}
                                  >
                                    <span class="lov-switch-thumb"></span>
                                  </button>
                                </div>
                              </div>`
                            )
                            .join('')
                    }
                  </div>
                </section>`
            }
          </div>
        </div>
      </div>
    `;

    root.querySelectorAll<HTMLButtonElement>('[data-scat]').forEach((btn) => {
      btn.addEventListener('click', () => {
        category = btn.dataset.scat as SettingNavId;
        notice = '';
        errorMsg = '';
        render();
      });
    });

    root.querySelectorAll<HTMLButtonElement>('[data-notify-key]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const key = btn.dataset.notifyKey as keyof typeof notifyPrefs | undefined;
        if (!key) return;
        notifyPrefs[key] = !notifyPrefs[key];
        notice = '通知订阅偏好已更新。';
        render();
      });
    });

    root.querySelector<HTMLInputElement>('[data-cal-start]')?.addEventListener('change', (e) => {
      draftStart = (e.currentTarget as HTMLInputElement).value;
    });
    root.querySelector<HTMLInputElement>('[data-cal-end]')?.addEventListener('change', (e) => {
      draftEnd = (e.currentTarget as HTMLInputElement).value;
    });

    root.querySelector<HTMLButtonElement>('[data-preview-impact]')?.addEventListener('click', async () => {
      errorMsg = '';
      impacts = await adapter.previewCalendarImpact(E7F_IDS.projectId, draftStart, draftEnd);
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-save-cal]')?.addEventListener('click', async () => {
      errorMsg = '';
      try {
        const updated = await adapter.saveWorkCalendar(E7F_IDS.projectId, draftStart, draftEnd, data.calendar.version);
        data = { ...data, calendar: updated };
        notice = `运行日历已保存至 v${updated.version}（${updated.workdayStart} - ${updated.workdayEnd}）`;
        impacts = [];
        render();
      } catch (err) {
        errorMsg = err instanceof Error ? err.message : String(err);
        render();
      }
    });

    root.querySelectorAll<HTMLButtonElement>('[data-toggle-rule]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        errorMsg = '';
        try {
          await adapter.toggleRuntimeRule(btn.dataset.toggleRule!, btn.dataset.ruleNext === 'true', Number(btn.dataset.ruleVer));
          data = await adapter.getRuntimeSettings(E7F_IDS.projectId);
          notice = '策略状态与版本回执已更新';
          render();
        } catch (err) {
          errorMsg = err instanceof Error ? err.message : String(err);
          render();
        }
      });
    });
  }

  render();
}
